package com.masaakis.order.application;import com.masaakis.security.StaffPrincipal;import org.springframework.stereotype.Service;import org.springframework.transaction.support.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;import java.io.IOException;import java.util.*;import java.util.concurrent.*;
@Service public class OrderEventStream{private record Scope(UUID tenant,UUID branch){}private final ConcurrentHashMap<Scope,CopyOnWriteArrayList<SseEmitter>>clients=new ConcurrentHashMap<>();
 public SseEmitter subscribe(StaffPrincipal p){p.require("read");Scope scope=new Scope(p.tenantId(),p.branchId());SseEmitter emitter=new SseEmitter(30*60_000L);clients.computeIfAbsent(scope,x->new CopyOnWriteArrayList<>()).add(emitter);Runnable remove=()->clients.getOrDefault(scope,new CopyOnWriteArrayList<>()).remove(emitter);emitter.onCompletion(remove);emitter.onTimeout(remove);emitter.onError(x->remove.run());try{emitter.send(SseEmitter.event().name("connected").data("ok"));}catch(IOException e){remove.run();}return emitter;}
 public void afterCommit(UUID tenant,UUID branch,String type){Runnable send=()->publish(new Scope(tenant,branch),type);if(TransactionSynchronizationManager.isSynchronizationActive())TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){send.run();}});else send.run();}
 private void publish(Scope scope,String type){for(SseEmitter e:clients.getOrDefault(scope,new CopyOnWriteArrayList<>()))try{e.send(SseEmitter.event().name("order").data(type));}catch(Exception x){e.complete();clients.getOrDefault(scope,new CopyOnWriteArrayList<>()).remove(e);}}
}
